using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Application.Bloco8; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Api.Controllers;
[ApiController,Authorize,Route("api/processos-digitais")] public sealed class ProcessosDigitaisBloco8Controller:ControllerBase {private readonly IProcessosDigitaisService _s;public ProcessosDigitaisBloco8Controller(IProcessosDigitaisService s)=>_s=s;[HttpGet("dashboard")]public async Task<ActionResult<ApiResponse<Bloco8DashboardDto>>> Dashboard(CancellationToken ct)=>From(await _s.DashboardAsync("processo_digital",ct));[HttpGet]public async Task<ActionResult<ApiResponse<PagedResult<Bloco8RegistroDto>>>> Listar([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>From(await _s.ListarAsync("processo_digital",pagina,tamanho,ct));[HttpPost]public async Task<ActionResult<ApiResponse<long>>> Criar(Bloco8RegistroRequest r,CancellationToken ct)=>From(await _s.CriarAsync("processo_digital",r,HttpContext.TraceIdentifier,ct));[HttpGet("{id:long}")]public async Task<ActionResult<ApiResponse<Bloco8RegistroDto>>> Obter(long id,CancellationToken ct)=>From(await _s.ObterAsync("processo_digital",id,ct));[HttpPost("{id:long}/encerrar")]public async Task<ActionResult> Encerrar(long id,ProcessoEncerrarRequest r,CancellationToken ct){var x=await _s.AlterarStatusAsync("processo_digital",id,"ENCERRADO",r.Justificativa,HttpContext.TraceIdentifier,ct);return x.IsSuccess?NoContent():BadRequest(x.Error);}[HttpPost("{id:long}/reabrir")]public async Task<ActionResult> Reabrir(long id,ProcessoReabrirRequest r,CancellationToken ct){var x=await _s.AlterarStatusAsync("processo_digital",id,"REABERTO",r.Justificativa,HttpContext.TraceIdentifier,ct);return x.IsSuccess?NoContent():BadRequest(x.Error);}private ActionResult<ApiResponse<T>> From<T>(Result<T> r)=>r.IsSuccess?Ok(ApiResponse<T>.Ok(r.Value!,correlationId:HttpContext.TraceIdentifier)):BadRequest(ApiResponse<T>.Fail(r.Error??"Falha.",HttpContext.TraceIdentifier));}
